import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;import java.util.*;import java.util.zip.*;
public class ScanDatStatus{public static void main(String[]a)throws Exception{try(var z=new ZipFile(a[0])){for(var e:Collections.list(z.entries()))if(e.getName().matches("classes[0-9]*\\.dex"))try(var in=z.getInputStream(e)){for(var c:new DexBackedDexFile(Opcodes.getDefault(),java.nio.ByteBuffer.wrap(in.readAllBytes())).getClasses())for(var m:c.getMethods())if(m.getImplementation()!=null){var list=new ArrayList<Instruction>();m.getImplementation().getInstructions().forEach(list::add);for(int k=0;k<list.size();k++)if(list.get(k) instanceof ReferenceInstruction r&&r.getReference() instanceof StringReference s&&s.getString().matches("(?is).*(dat.?ochi|dat.?drop|dat落ち|is.?dead|thread.?status).*")){System.out.println(m+" STRING "+s.getString());for(int j=Math.max(0,k-16);j<Math.min(list.size(),k+7);j++){var i=list.get(j);System.out.println(" "+i.getOpcode()+(i instanceof ReferenceInstruction rr?" "+rr.getReference():"")+(i instanceof NarrowLiteralInstruction n?" #"+n.getNarrowLiteral():""));}}}}}}}
